-- Migration 0012 stored a short validation report (no checks, partial metrics) for
-- HOLY_GRAIL_15M and INSIDE_BAR_15M, and the dashboard's Strategy Lab, which reads
-- checks, win rate, profit factor and drawdown, crashed on it. Replace both reports
-- with the full shape, from the same 20-month backtest.
UPDATE strategy_versions SET validation = '{"status":"REJECTED","source":"20-month backtest, Mar 2025 – Nov 2026, 40 NSE stocks, production rules","generatedAt":1795717800000,"checks":[{"name":"BACKTEST_20_MONTHS","passed":false,"detail":"20-month backtest: 278 trades, -0.127R a trade, PF 0.72 (needs a positive result)"}],"outOfSample":{"trades":278,"expectancyR":-0.127,"winRate":0.378,"profitFactor":0.72,"maxDrawdownPct":10.9,"netPnl":-4608},"full":{"trades":278,"expectancyR":-0.127,"winRate":0.378,"profitFactor":0.72,"maxDrawdownPct":10.9,"netPnl":-4608},"weaknesses":["loses after charges over 20 months (-0.127R a trade, 278 trades)"]}'::jsonb
WHERE strategy_id = 'INSIDE_BAR_15M' AND status = 'REJECTED' AND validation->>'source' LIKE '20-month backtest%';
UPDATE strategy_versions SET validation = '{"status":"REJECTED","source":"20-month backtest, Mar 2025 – Nov 2026, 40 NSE stocks, production rules","generatedAt":1795717800000,"checks":[{"name":"BACKTEST_20_MONTHS","passed":false,"detail":"20-month backtest: 606 trades, -0.258R a trade, PF 0.48 (needs a positive result)"}],"outOfSample":{"trades":606,"expectancyR":-0.258,"winRate":0.325,"profitFactor":0.48,"maxDrawdownPct":37.7,"netPnl":-17058},"full":{"trades":606,"expectancyR":-0.258,"winRate":0.325,"profitFactor":0.48,"maxDrawdownPct":37.7,"netPnl":-17058},"weaknesses":["loses after charges over 20 months (-0.258R a trade, 606 trades)"]}'::jsonb
WHERE strategy_id = 'HOLY_GRAIL_15M' AND status = 'REJECTED' AND validation->>'source' LIKE '20-month backtest%';
